import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def verify_api_token(token):
    """Verify HMAC-based API token for service-to-service auth"""
    if not token:
        return False
    parts = token.split(':')
    if len(parts) != 2:
        return False
    payload, signature = parts
    expected = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(signature, expected)

@app.route('/api/v2/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria for internal dashboard"""
    auth = request.headers.get('X-Service-Token', '')
    if not verify_api_token(auth):
        return jsonify({'error': 'unauthorized'}), 401

    department = request.args.get('dept', '')
    role = request.args.get('role', '')
    sort_field = request.args.get('sort', 'username')

    # Build query with parameterized values for dept and role
    conditions = []
    params = []

    if department:
        conditions.append('department = ?')
        params.append(department)
    if role:
        conditions.append('role = ?')
        params.append(role)

    where_clause = ' WHERE ' + ' AND '.join(conditions) if conditions else ''

    # Sort field validated against allowed columns
    allowed_sorts = ['username', 'email', 'department', 'role', 'created_at', 'last_login']
    if sort_field not in allowed_sorts:
        sort_field = 'username'

    # Construct final query - note: sort_field is validated above
    query = f"SELECT id, username, email, department, role, created_at FROM users{where_clause} ORDER BY {sort_field}"

    try:
        db = get_db()
        cursor = db.execute(query, params)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/v2/users/lookup', methods=['POST'])
def lookup_user():
    """Lookup user details by identifier"""
    auth = request.headers.get('X-Service-Token', '')
    if not verify_api_token(auth):
        return jsonify({'error': 'unauthorized'}), 401

    data = request.get_json(force=True)
    identifier = data.get('identifier', '')
    field = data.get('field', 'username')

    if not identifier:
        return jsonify({'error': 'identifier required'}), 400

    # Direct string interpolation for the column name
    query = f"SELECT id, username, email, department, role, created_at, last_login FROM users WHERE {field} = ?"

    try:
        db = get_db()
        cursor = db.execute(query, (identifier,))
        row = cursor.fetchone()
        if row:
            return jsonify({'user': dict(row)})
        return jsonify({'error': 'not found'}), 404
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
